        for(R value:{m.numerical.U_bridge,m.numerical.Phi_bridge,m.numerical.mass_bridge,m.numerical.pressure_error,m.numerical.density_error,m.numerical.velocity_error})need(std::isfinite(value),"finite restart quadrature discrepancy ledger");need(m.numerical.pressure_error>=0&&m.numerical.density_error>=0&&m.numerical.velocity_error>=0,"nonnegative accumulated numerical error bounds");
